create table xxcus.xxfnd_attachment_blk_entities (
    function_code         varchar2(60 byte) not null enable,
    block_code            varchar2(60 byte) not null enable,
    entity_name           varchar2(60 byte) not null enable,
    pk1_page_item         varchar2(255 byte) not null enable,
    pk2_page_item         varchar2(255 byte),
    pk3_page_item         varchar2(255 byte),
    pk4_page_item         varchar2(255 byte),
    pk5_page_item         varchar2(255 byte),
    insert_allowed_flag   varchar2(1 byte) default 'Y' not null enable,
    update_allowed_flag   varchar2(1 byte) default 'Y' not null enable,
    delete_allowed_flag   varchar2(1 byte) default 'N' not null enable,
    display_sequence      number,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_attachment_blk_entities
    add constraint xxfnd_att_blk_entities_ck1
        check ( insert_allowed_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_attachment_blk_entities
    add constraint xxfnd_att_blk_entities_ck2
        check ( update_allowed_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_attachment_blk_entities
    add constraint xxfnd_att_blk_entities_ck3
        check ( delete_allowed_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_attachment_blk_entities
    add constraint xxfnd_att_blk_entities_pk
        primary key ( function_code,
                      block_code,
                      entity_name )
            using index enable;


